def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    twos = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    r0 = min(r for r, c in twos)
    r1 = max(r for r, c in twos)
    c0 = min(c for r, c in twos)
    c1 = max(c for r, c in twos)

    # Extend each edge of the solid 2 rectangle along its row/column,
    # stopping at the first nonzero marker.
    for r in range(r0, r1 + 1):
        if not any(grid[r][c] != 0 for c in range(c0)):
            for c in range(c0):
                out[r][c] = 2
        if not any(grid[r][c] != 0 for c in range(c1 + 1, w)):
            for c in range(c1 + 1, w):
                out[r][c] = 2
    for c in range(c0, c1 + 1):
        if not any(grid[r][c] != 0 for r in range(r0)):
            for r in range(r0):
                out[r][c] = 2
        if not any(grid[r][c] != 0 for r in range(r1 + 1, h)):
            for r in range(r1 + 1, h):
                out[r][c] = 2
    return out

